krpano.action:

set(layer[btn_tien_ich].is_active, false);
set(layer[btn_tien_ich].backgroundcolor, 0x091D36);
set(layer[btn_tien_ich].css, 'text-align:center; color:#fff; font-family:UTM Optima; font-size:10px; font-weight:500;');
set(layer[btn_can_ho_mau].is_active, false);
set(layer[btn_can_ho_mau].backgroundcolor, 0x091D36);
set(layer[btn_can_ho_mau].css, 'text-align:center; color:#fff; font-family:UTM Optima; font-size:10px; font-weight:500;');
set(layer[btn_sanh_sapphire].is_active, false);
set(layer[btn_sanh_sapphire].backgroundcolor, 0x091D36);
set(layer[btn_sanh_sapphire].css, 'text-align:center; color:#fff; font-family:UTM Optima; font-size:10px; font-weight:500;');


if(get(scene[get(xml.scene)].name) == 'scene_pin_1',
    set(layer[btn_tien_ich].is_active, true);
    set(layer[btn_tien_ich].backgroundcolor, 0x1F2937);
    set(layer[btn_tien_ich].css, 'text-align:center; color:#EACDA6; font-family:UTM Optima; font-size:10px; font-weight:500;');
);
if(get(scene[get(xml.scene)].name) == 'scene_pin_18',
    set(layer[btn_sanh_sapphire].is_active, true);
    set(layer[btn_sanh_sapphire].backgroundcolor, 0x1F2937);
    set(layer[btn_sanh_sapphire].css, 'text-align:center; color:#EACDA6; font-family:UTM Optima; font-size:10px; font-weight:500;');
);

if(device.mobile OR device.tablet OR stagewidth LT 1024,
    set(layer[button_container].scale, 0.8);
    set(layer[button_container].css, 'overflow:hidden;overflow-x:scroll;padding:5px 10px;');
    set(layer[button_container].x, 0);
    set(layer[button_container].y, 85);
    set(layer[btn_tien_ich].width, 75);
    set(layer[btn_tien_ich].css, 'font-size:8px; color:#fff; text-align:center; white-space:nowrap;');
    set(layer[btn_tien_ich].x, 10);
    set(layer[btn_can_ho_mau].width, 75);
    set(layer[btn_can_ho_mau].css, 'font-size:8px; color:#fff; text-align:center; white-space:nowrap;');
    set(layer[btn_can_ho_mau].x, 89);
    set(layer[btn_sanh_sapphire].width, 75);
    set(layer[btn_sanh_sapphire].css, 'font-size:8px; color:#fff; text-align:center; white-space:nowrap;');
    set(layer[btn_sanh_sapphire].x, 168);
,
    set(layer[button_container].scale, 1.0);
    set(layer[button_container].x, 0);
    set(layer[button_container].y, 50);
);
